begin;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',m; end if; end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q; exception when others then return; end; raise exception 'Expected rejection: %',q; end$$;
insert into auth.users(id,email_confirmed_at) select ('79000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now() from generate_series(1,4)n;
insert into public.staff_roles(user_id,role) values('79000000-0000-4000-8000-000000000003','admin'),('79000000-0000-4000-8000-000000000004','membership_reviewer');
insert into private.market_projects(id,buyer_id,status,brief) values('79000000-0000-4000-8000-000000000010','79000000-0000-4000-8000-000000000001','review','{"title":"Original brief","deliverables":"Board","acceptance":"Test"}');
set local role anon;
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','request_changes','{"note":"Clarify the test requirements"}')$q$);
set local role authenticated;
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000004',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','request_changes','{"note":"Clarify the test requirements"}')$q$);
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test"}')$q$);
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000003',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','request_changes','{"note":"Short"}')$q$);
select pg_temp.ok(public.market_project_action('79000000-0000-4000-8000-000000000010','request_changes','{"note":"Clarify the test requirements"}')->'project'->>'status'='draft','admin returns review to draft');
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test"}')$q$);
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000002',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test"}')$q$);
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board"}')$q$);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test","budget_min":100,"budget_max":50}')$q$);
select pg_temp.ok(public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited brief","deliverables":"Board","acceptance":"Measured test"}')->'project'->'brief'->>'title'='Edited brief','buyer edits draft');
select pg_temp.ok(public.market_project_action('79000000-0000-4000-8000-000000000010','submit_review')->'project'->>'status'='review','buyer resubmits existing action');
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000003',true);
select public.market_project_action('79000000-0000-4000-8000-000000000010','publish');
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','request_changes','{"note":"Attempt to reopen published scope"}')$q$);
select set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',true);
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test"}')$q$);
reset role;
update private.market_projects set status='draft' where id='79000000-0000-4000-8000-000000000010';
insert into private.market_milestones(project_id,position,terms,funded) values('79000000-0000-4000-8000-000000000010',1,'{"title":"Reserved scope","serviceAmount":100}',true);
set local role authenticated;
select pg_temp.denied($q$select public.market_project_action('79000000-0000-4000-8000-000000000010','edit_brief','{"title":"Edited","deliverables":"Board","acceptance":"Test"}')$q$);
reset role;
select pg_temp.ok((select count(*)=4 from private.market_activity where project_id='79000000-0000-4000-8000-000000000010'),'all actions audited');
select pg_temp.ok((select payload->'before'->>'title'='Original brief' and payload->'after'->>'title'='Edited brief' from private.market_activity where project_id='79000000-0000-4000-8000-000000000010' and event='edit_brief'),'prior draft retained in audit');
select pg_temp.ok(not has_function_privilege('authenticated','private.market_project_action(uuid,text,jsonb)','execute'),'base action not callable directly');
rollback;
